package dev.gustavopere.rpgskilltree.runtime;
import dev.gustavopere.rpgskilltree.core.A0061A0080CombatState;import dev.gustavopere.rpgskilltree.core.CombatPerkNodeBinding;import dev.gustavopere.rpgskilltree.core.CombatPerkRanks;import dev.gustavopere.rpgskilltree.core.StationaryStateService;import java.util.HashMap;import java.util.Map;import net.minecraft.server.level.ServerPlayer;
public final class A0061A0080RuntimeState{private static final A0061A0080CombatState STATE=new A0061A0080CombatState();private static final StationaryStateService STATIONARY=new StationaryStateService();private static final Map<String,Map<String,Integer>>LAST_EFFECTIVE_RANKS=new HashMap<>();private A0061A0080RuntimeState(){}public static A0061A0080CombatState state(){return STATE;}public static StationaryStateService stationary(){return STATIONARY;}public static synchronized CombatPerkRanks ranks(ServerPlayer p){CombatPerkRanks e=CombatPerkAvailabilityRuntime.effectiveRanks(CombatPerkNodeBinding.ranks(PlayerProgressionRuntime.get(p).passiveNodes()));String a=actorId(p);Map<String,Integer>prev=LAST_EFFECTIVE_RANKS.put(a,e.ranks());if(prev!=null&&!prev.equals(e.ranks())){STATE.clearActor(a);STATIONARY.invalidate(a);}return e;}public static String actorId(ServerPlayer p){return p.getUUID().toString();}public static boolean isStationary(ServerPlayer p){return STATIONARY.isStationary(actorId(p));}public static synchronized void clear(ServerPlayer p){String a=actorId(p);LAST_EFFECTIVE_RANKS.remove(a);STATE.clearActor(a);STATIONARY.invalidate(a);}public static synchronized void clearAll(){LAST_EFFECTIVE_RANKS.clear();STATE.clearAll();STATIONARY.clearAll();}}
